class ValidateModule{#default_rules={};#default_messages={};constructor(){this.#default_rules={required:this.#checkRequired.bind(this),email:this.#checkValidEmail.bind(this),phone:this.#checkValidPhone.bind(this),number:this.#checkNumber.bind(this),array:this.#checkIsArray.bind(this)},this.#default_messages={required:":attribute is required field ",email:":attribute is not a valid email",phone:":attribute is not a valid phone number",number:":attribute is must be and number type",array:":attribute is must an array type"}}#checkRequired=async e=>""!==e.trim();#checkValidEmail=async e=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);#checkValidPhone=async e=>/^\d{10}$/.test(e);#checkNumber=async e=>!isNaN(e);#checkIsArray=async e=>Array.isArray(e);validateWithInputs=async(e,t=null)=>{this.#default_messages=Object.assign({},this.#default_messages,t);let a=!1;var s,i,r=[];for([s,i]of Object.entries(e)){var l,u=$(`input[name=${s}].handle-request`).val();for(l of i)if(!await this.#default_rules[l](u)){a=!0,r.push(this.#default_messages[l].replace(/:attribute/gim,s));break}}return{errors:r,fail:a}};showErrorMessage=async(e,s,i)=>{$(s).html(""),$(e).each(function(t){var e=$(this).attr("name"),a=new RegExp(`\\b${e}\\b`,"gim");for(let e=0;e<i.length;e++)a.test(i[e])&&$(s).eq(t).html(i[e].replaceAll("_"," "))})}}export default ValidateModule;